    <div id="app"></div>

    <script>
      const state = {
        open: false,
      };

      const app = document.getElementById("app");

      function App() {
        return `
          <main class="app">
            <section class="page" aria-label="Image preview page">
              ${Hero()}
              ${ImagePreview()}
            </section>
            ${DeleteDialog()}
          </main>
        `;
      }

      function Hero() {
        return `
          <div class="hero">
            <p class="eyebrow">Library preview</p>
            <h1>Review your image before removing it from your library.</h1>
            <p>
              A clean confirmation step helps prevent accidental deletes while keeping the preview
              experience fast and focused.
            </p>
          </div>
        `;
      }

      function ImagePreview() {
        return `
          <article class="preview-card" aria-labelledby="image-title">
            <img
              class="preview-image"
              src="https://images.unsplash.com/photo-1493225457124-a3eb161ffa5f?auto=format&fit=crop&w=1200&q=80"
              alt="Stylish workspace with soft lighting and a laptop"
            />
            <div class="preview-meta">
              <div class="title-group">
                <h2 id="image-title">Workspace editorial shot</h2>
                <p>Saved to your library • 4.8 MB</p>
              </div>
              <button class="trigger" type="button" data-action="open-dialog">
                Delete image
              </button>
            </div>
          </article>
        `;
      }

      function DeleteDialog() {
        return `
          <div class="modal-layer" id="delete-dialog" hidden>
            <div
              class="dialog"
              role="dialog"
              aria-modal="true"
              aria-labelledby="dialog-title"
              aria-describedby="dialog-description"
              tabindex="-1"
            >
              <div class="dialog__header">
                <div class="dialog__icon" aria-hidden="true">!</div>
              </div>
              <div class="dialog__body">
                <h2 id="dialog-title">Delete this image?</h2>
                <p id="dialog-description">
                  This will remove the image from your library and cannot be undone.
                </p>
              </div>
              <div class="dialog__actions">
                <button class="secondary" type="button" data-action="close-dialog">Cancel</button>
                <button class="danger" type="button">Delete</button>
              </div>
            </div>
          </div>
        `;
      }

      function render() {
        app.innerHTML = App();
        syncDialog();
      }

      function syncDialog() {
        const dialog = document.getElementById("delete-dialog");
        if (!dialog) return;
        dialog.hidden = !state.open;
        if (state.open) {
          const panel = dialog.querySelector('[role="dialog"]');
          panel.focus();
        }
      }

      document.addEventListener("click", (event) => {
        const target = event.target.closest("[data-action]");
        if (!target) return;

        const action = target.dataset.action;
        if (action === "open-dialog") {
          state.open = true;
          syncDialog();
        }

        if (action === "close-dialog") {
          state.open = false;
          syncDialog();
