        if (event.key === "Escape" && state.open) {
          state.open = false;
          syncDialog();
        }
      });

      document.addEventListener("click", (event) => {
        const layer = event.target.closest("#delete-dialog");
        if (layer && event.target === layer) {
          state.open = false;
          syncDialog();
        }
      });

      render();
    </script>
